$ErrorActionPreference = "Stop"\n$source = Split-Path -Parent $MyInvocation.MyCommand.Path\n$target = Read-Host "Ruta de tu proyecto EvolvAI actual (ej. C:\\Users\\i2mTo\\EvolvAI-v0.7.8\\evolvai075)"\nif (-not (Test-Path (Join-Path $target "pubspec.yaml"))) { throw "No se encontró pubspec.yaml en $target" }\nWrite-Host "Actualizando lib, test y pubspec.yaml..." -ForegroundColor Cyan\nCopy-Item (Join-Path $source "lib") (Join-Path $target "lib") -Recurse -Force\nCopy-Item (Join-Path $source "test") (Join-Path $target "test") -Recurse -Force\nCopy-Item (Join-Path $source "pubspec.yaml") (Join-Path $target "pubspec.yaml") -Force\nCopy-Item (Join-Path $source "CHANGELOG_V0_7_9.md") (Join-Path $target "CHANGELOG_V0_7_9.md") -Force\nWrite-Host "Actualización completada. La carpeta android NO se ha tocado." -ForegroundColor Green\n